import {readFile,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
const revision=process.argv[2]??'v1',root='output/access-directory-rebased-acceptance-20261005/targeted-rollback'+(revision==='v2'?'/v2-searchpath':revision==='v3'?'/v3-context':''),m=JSON.parse(await readFile(root+'/'+(revision==='v3'?'V3-MANIFEST.json':revision==='v2'?'V2-MANIFEST.json':'TARGETED-MANIFEST.json'),'utf8')),sha=x=>createHash('sha256').update(x).digest('hex'),privateRoot='./LOCAL_USER/AppData/Local/FVI-QA-Private-20260925';
const v=await readFile('./.private/CREDENTIALS.md','utf8'),a=v.indexOf('<!-- FVI_CANONICAL_OPERATIONAL_CREDENTIALS_BEGIN -->'),z=v.indexOf('<!-- FVI_CANONICAL_OPERATIONAL_CREDENTIALS_END -->');if(a<0||z<=a)throw new Error('FVI authority boundary');const token=v.slice(a,z).split(/\r?\n/).find(x=>/^\|\s*`SUPABASE_ACCESS_TOKEN`\s*\|/.test(x))?.split('|')[2]?.trim().replace(/^`|`$/g,'');if(!/^sbp_/.test(token??''))throw new Error('FVI authority absent');
const refs={PROD:'YOUR_PROJECT_REF',DEV:'YOUR_PROJECT_REF'},identity="SELECT current_setting('server_version_num') AS engine,(SELECT count(*)::int FROM supabase_migrations.schema_migrations) AS ledger,(SELECT max(version::text) FROM supabase_migrations.schema_migrations) AS latest";
async function query(ref,sql,readonly){const r=await fetch('https://api.supabase.com/v1/projects/'+ref+'/database/query',{method:'POST',headers:{authorization:'Bearer '+token,'content-type':'application/json'},body:JSON.stringify({query:sql,read_only:readonly}),signal:AbortSignal.timeout(75000)});const raw=await r.text();if(!r.ok){const file=privateRoot+'/FVI-STRUCTURE-TARGETED-ROLLBACK-ERROR-'+Date.now()+'.json';await writeFile(file,JSON.stringify({at:new Date().toISOString(),ref,http:r.status,raw},null,2),{flag:'wx'});throw new Error('Targeted structure rollback HTTP'+r.status+'; diagnostic private');}return JSON.parse(raw);}
const results=[];for(const p of m.packets){if(refs[p.environment]!==p.ref)throw new Error('Exact target ref changed');const sql=await readFile(root+'/'+p.file,'utf8');if(sha(sql)!==p.sha256||!sql.endsWith('ROLLBACK;\n')||!sql.startsWith('-- '+p.environment))throw new Error('Frozen targeted rollback mismatch');const before=(await query(p.ref,identity,true))[0];if(before.engine!=='170006'||before.ledger!==p.initialLedger||before.latest!==p.latest)throw new Error('Actual initial ledger changed; no DDL');const execution=await query(p.ref,sql,false);const after=(await query(p.ref,identity,true))[0];if(JSON.stringify(before)!==JSON.stringify(after))throw new Error('After rollback ledger changed');const receipt=privateRoot+'/FVI-STRUCTURE-TARGETED-'+p.environment+'-ROLLBACK-'+Date.now()+'.json';await writeFile(receipt,JSON.stringify({at:new Date().toISOString(),environment:p.environment,ref:p.ref,sourceSha256:sha(sql),before,execution,after,committed:false,targetedProtection:'10 structure tables + old ledger/audit row hashes; untouched identity/session/storage operation proof + old authority metadata'},null,2),{flag:'wx'});results.push({environment:p.environment,ref:p.ref,sourceSha256:sha(sql),ledger:after.ledger,latest:after.latest,rollbackPassed:true,committed:false,receipt});console.log(JSON.stringify(results.at(-1)));}
await writeFile('docs/evidence/FVI_STRUCTURE_TARGETED_ROLLBACK_2026-10-05-'+Date.now()+'.json',JSON.stringify({at:new Date().toISOString(),results,noSQLCommit:true},null,2),{flag:'wx'});
